import Foundation

/// A palette: RGBA entries spaced evenly from the darkest (index 0) to the brightest. Values run 0 … 3
/// and more, where 1 is SDR white; alpha is ignored. A Float32Array in the original.
public struct Palette: Sendable {
    public var rgba: [Float]
    public var name: String

    public init(rgba: [Float], name: String) {
        self.rgba = rgba
        self.name = name
    }

    public var entryCount: Int { rgba.count / 4 }
}

/// palette.js.
public enum Palettes {
    /// How often GenerateRandomPalette makes a new palette instead of picking a hand-tuned one. [0 … 1]
    static let randomPaletteFraction = 0.02
    /// Don't go crazy in production palettes.
    static let randomPaletteWonkiness = 0.6

    /// `GenerateRandomPalette()`: usually one of the hand-tuned palettes, sometimes a random one.
    public static func random(using random: inout RandomSource) -> Palette {
        if random.next() > randomPaletteFraction {
            // A pre-made palette.
            let n = presets.count
            var k = toInt32((random.next() * Double(n)).rounded(.down))
            k = min(k, n - 1)
            return Palette(rgba: deserialize(presets[max(0, k)]), name: "Palette \(k)")
        }

        // A random one.
        let minSum = 5.5
        let maxSum = 6.5
        var r = 0.01 + random.next() * maxSum * (2.0 / 3.0)
        var g = 0.01 + random.next() * maxSum * (2.0 / 3.0)
        var b = 0.01 + random.next() * maxSum * (2.0 / 3.0)
        let sum = r + g + b
        if sum < minSum {
            r = r * minSum / sum
            g = g * minSum / sum
            b = b * minSum / sum
        }
        if sum > maxSum {
            r = r * maxSum / sum
            g = g * maxSum / sum
            b = b * maxSum / sum
        }

        // Powers: 0.5 is low contrast (shadows too bright) but can suit one channel; 1.0 is a bit low
        // too; 1.5 has good contrast; 2.0 has quite dark shadows, fine on one channel.
        let rp = pow(2.0, -0.7 + 2.0 * random.next())
        let gp = pow(2.0, -0.7 + 2.0 * random.next())
        let bp = pow(2.0, -0.7 + 2.0 * random.next())

        let n = 8
        var ret = [Float](repeating: 0, count: n * 4)
        for i in 0..<n {
            let t = Double(i) * (1.0 / Double(n - 1))
            ret[i * 4 + 0] = Float(r * pow(t, rp))
            ret[i * 4 + 1] = Float(g * pow(t, gp))
            ret[i * 4 + 2] = Float(b * pow(t, bp))
            ret[i * 4 + 3] = 1.0
        }

        // Sometimes, perturb it at random.
        let randPower = jsMax(0.0, jsMin(1.0, random.next() * 1.8 - 0.2)) * randomPaletteWonkiness
        var sr = 1.0
        var sg = 1.0
        var sb = 1.0
        for k in 1..<n {
            sr *= pow(0.78 + 0.53 * random.next(), randPower)
            sg *= pow(0.78 + 0.53 * random.next(), randPower)
            sb *= pow(0.78 + 0.53 * random.next(), randPower)
            ret[k * 4 + 0] = Float(Double(ret[k * 4 + 0]) * sr)
            ret[k * 4 + 1] = Float(Double(ret[k * 4 + 1]) * sg)
            ret[k * 4 + 2] = Float(Double(ret[k * 4 + 2]) * sb)
        }
        return Palette(rgba: ret, name: "Random palette")
    }

    /// `DeserializePalette(str)`: "N  r g b  r g b …" to RGBA. Missing or unreadable numbers become NaN,
    /// as parseFloat makes them; the original throws on a bad count, this returns no entries.
    public static func deserialize(_ text: String) -> [Float] {
        let parts = text.split(whereSeparator: { $0 == " " || $0 == "\t" || $0 == "\n" }).map(String.init)
        guard let first = parts.first, let n = Int(first), n >= 0 else { return [] }
        func number(_ i: Int) -> Float {
            // parseFloat gives the nearest double; the Float32Array store then rounds that.
            Float(i < parts.count ? Double(parts[i]) ?? .nan : .nan)
        }
        var out = [Float](repeating: 0, count: n * 4)
        for i in 0..<n {
            out[i * 4 + 0] = number(i * 3 + 1)
            out[i * 4 + 1] = number(i * 3 + 2)
            out[i * 4 + 2] = number(i * 3 + 3)
            out[i * 4 + 3] = 1.0
        }
        return out
    }

    /// `SamplePalette(palette, t)`: the colour at t ∈ [0, 1], linearly between entries.
    public static func sample(_ palette: [Float], at t: Double) -> (r: Double, g: Double, b: Double) {
        let n = toInt32(Double(palette.count) / 4)
        let t = jsMax(0.0, jsMin(1.0, t))
        let fx = t * Double(n - 1)
        let i0 = toInt32(fx.rounded(.down))
        let i1 = min(i0 + 1, n - 1)
        let dx = fx - Double(i0)
        let r = palette.js(i0 * 4 + 0) * (1.0 - dx) + (dx) * palette.js(i1 * 4 + 0)
        let g = palette.js(i0 * 4 + 1) * (1.0 - dx) + (dx) * palette.js(i1 * 4 + 1)
        let b = palette.js(i0 * 4 + 2) * (1.0 - dx) + (dx) * palette.js(i1 * 4 + 2)
        return (r, g, b)
    }

    /// `HdrToSdr(t, r, g, b, max_rgb_in_palette)`: squeezes an HDR palette entry into SDR. `t` is where the
    /// entry sits in the palette, `maxRGBInPalette` the brightest channel anywhere in it.
    ///
    /// Black comes back NaN, as in the original (0/0 in the midtone boost); the original's upload then
    /// turns NaN into 0, so it still draws black.
    public static func hdrToSdr(t: Double, r: Double, g: Double, b: Double, maxRGBInPalette: Double) -> SIMD3<Float> {
        // Don't brighten dark colours; only darken over-bright ones.
        var maxRGB = jsMax(maxRGBInPalette, 1.0)
        var col: [Float] = [Float(r), Float(g), Float(b)]  // a Float32Array(3)

        // How much of the remap is plain darkening. 1.0 would darken until max_rgb == 1. Mostly
        // darken: it keeps the colours' r:g:b ratios, and people with SDR screens tend to run them bright.
        let darkenFraction = 0.57
        let scale = pow(1.0 / maxRGB, darkenFraction)
        for c in 0..<3 { col[c] = Float(Double(col[c]) * scale) }
        maxRGB *= scale

        // Fade toward white at the top of the palette.
        let desaturateAggressiveness = 0.25
        let desaturateAmount = jsMax(0.0, t + maxRGB - 2.0) * desaturateAggressiveness
        for c in 0..<3 { col[c] = Float(lerp(Double(col[c]), 1.0, desaturateAmount)) }

        // A mild boost to the luma of midtones and shadows; a lower power brightens midtones more. Lots
        // of max(r, g, b) goes into the luma so rich colours count as bright and their midtones get
        // brightened about as much as greys.
        let midtoneLumaPower = 0.87
        let c0 = Double(col[0])
        let c1 = Double(col[1])
        let c2 = Double(col[2])
        let luma = (c0 + c1 + c2 + 5 * jsMax(c0, jsMax(c1, c2))) / 8.0
        let luma2 = pow(luma, midtoneLumaPower)
        let scale2 = luma2 / luma
        for c in 0..<3 { col[c] = Float(Double(col[c]) * scale2) }

        // A mild deep-shadow darkening.
        let shadowDarkening = 0.4
        let fullShadow = 0.0
        let zeroShadow = 0.48
        let maxRGBNow = jsMax(Double(col[0]), jsMax(Double(col[1]), Double(col[2])))
        let isShadow = jsMax(0.0, jsMin(1.0, (maxRGBNow - zeroShadow) / (fullShadow - zeroShadow)))
        for c in 0..<3 { col[c] = Float(Double(col[c]) * (1.0 - isShadow * shadowDarkening)) }

        // Clamp to SDR white.
        for c in 0..<3 { col[c] = Float(jsMin(1.0, Double(col[c]))) }
        return SIMD3(col[0], col[1], col[2])
    }

